"""Dyadic predictors for safe odd-N multiplier jumps m->m+2.

The only skipped multipliers are m+1 == 2 (mod 4), which can never occur in
an integer difference of two squares when N is odd. For source m=1,5,...,97
we store

    C_m = floor(2^2053 * (sqrt((m+2)/m) - 1)).

Lower precisions are exact right shifts. N above 4096 bits uses the same
formula through a cached dynamic constructor.
"""

from __future__ import annotations

from functools import lru_cache
from math import isqrt

SOURCE_MULTIPLIERS = (1, 5, 9, 13, 17, 21, 25, 29, 33, 37, 41, 45, 49, 53, 57, 61, 65, 69, 73, 77, 81, 85, 89, 93, 97)
MAX_STATIC_N_BITS = 4096
MAX_STATIC_FRACTION_BITS = 2053
ENTRY_BYTES = 257
ENTRY_COUNT = 25
RAW_PAYLOAD_BYTES = 6425
TABLE_SHA256 = "a42a3c1aaf8561341dcaf8f196fb8afa0ce5ceb028a1a68458b669d6e3b4ddcb"

_PAYLOAD = bytes.fromhex(
    ""
)

if len(_PAYLOAD) != RAW_PAYLOAD_BYTES:
    raise AssertionError("jump2 predictor payload length mismatch")


def _fraction_bits_for_n_bits(n_bits: int) -> int:
    if isinstance(n_bits, bool) or not isinstance(n_bits, int) or n_bits <= 0:
        raise ValueError("n_bits must be a positive integer")
    return (n_bits + 8) // 2 + 1


@lru_cache(maxsize=1)
def high_precision_constants() -> tuple[int, ...]:
    return tuple(
        int.from_bytes(_PAYLOAD[i * ENTRY_BYTES : (i + 1) * ENTRY_BYTES], "big")
        for i in range(ENTRY_COUNT)
    )


def _generate_constant(source_multiplier: int, fraction_bits: int) -> int:
    scale = 1 << fraction_bits
    return (
        isqrt((((source_multiplier + 2) << (2 * fraction_bits)) // source_multiplier))
        - scale
    )


@lru_cache(maxsize=None)
def jump2_constant_for_n_bits(
    n_bits: int, source_multiplier: int
) -> tuple[int, int, str]:
    if source_multiplier not in SOURCE_MULTIPLIERS:
        raise ValueError("source_multiplier must be one of 1,5,...,97")
    B = _fraction_bits_for_n_bits(n_bits)
    if n_bits <= MAX_STATIC_N_BITS:
        index = (source_multiplier - 1) // 4
        constant = high_precision_constants()[index] >> (
            MAX_STATIC_FRACTION_BITS - B
        )
        return B, constant, "STATIC"
    return B, _generate_constant(source_multiplier, B), "DYNAMIC_CACHED"


def regenerated_payload() -> bytes:
    return b"".join(
        _generate_constant(m, MAX_STATIC_FRACTION_BITS).to_bytes(ENTRY_BYTES, "big")
        for m in SOURCE_MULTIPLIERS
    )


__all__ = [
    "SOURCE_MULTIPLIERS",
    "MAX_STATIC_N_BITS",
    "MAX_STATIC_FRACTION_BITS",
    "ENTRY_BYTES",
    "ENTRY_COUNT",
    "RAW_PAYLOAD_BYTES",
    "TABLE_SHA256",
    "high_precision_constants",
    "jump2_constant_for_n_bits",
    "regenerated_payload",
]
